import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"13.1 安全作业组织措施与技术措施","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-1-an-quan-zuo-ye-zu-zhi-cuo-shi-yu-ji-shu-cuo-shi.md","filePath":"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-1-an-quan-zuo-ye-zu-zhi-cuo-shi-yu-ji-shu-cuo-shi.md","lastUpdated":1793096070000}'),i={name:"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-1-an-quan-zuo-ye-zu-zhi-cuo-shi-yu-ji-shu-cuo-shi.md"};function l(n,t,s,u,d,h){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_13-1-安全作业组织措施与技术措施" tabindex="-1">13.1 安全作业组织措施与技术措施 <a class="header-anchor" href="#_13-1-安全作业组织措施与技术措施" aria-label="Permalink to &quot;13.1 安全作业组织措施与技术措施&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电工作业要&quot;双保险&quot;:一是靠<strong>制度管人</strong>(组织措施),二是靠<strong>操作保命</strong>(技术措施)。这一节掌握&quot;保证安全的组织措施&quot;和&quot;技术措施&quot;各有哪些——这是安全知识考核的高频考点。</p><h2 id="一、保证安全的组织措施-制度层面" tabindex="-1">一、保证安全的组织措施(制度层面) <a class="header-anchor" href="#一、保证安全的组织措施-制度层面" aria-label="Permalink to &quot;一、保证安全的组织措施(制度层面)&quot;">​</a></h2><p>靠规章制度把&quot;谁能干、怎么批、谁来看着干、干到哪一步&quot;规定清楚:</p><table tabindex="0"><thead><tr><th>措施</th><th>内容</th></tr></thead><tbody><tr><td><strong>工作票制度</strong></td><td>作业前填写工作票,明确任务、地点、安全措施,经批准才开工</td></tr><tr><td><strong>工作许可制度</strong></td><td>工作负责人得到许可后,现场确认安全措施到位才能开工</td></tr><tr><td><strong>工作监护制度</strong></td><td>作业时有专人监护,监护人不离岗、不兼做其他工作</td></tr><tr><td><strong>工作间断、转移和终结制度</strong></td><td>间断、换地点、收工都要办理相应手续,终结后恢复送电</td></tr></tbody></table><blockquote><p>💡 通俗理解:<strong>&quot;先审批、再许可、有人监护、有始有终&quot;</strong>——组织措施是用流程堵住疏忽。</p></blockquote><blockquote><p>⚠️ 判断题常考:低压电气作业也要执行工作票、许可、监护等制度;工作负责人不能兼任与工作无关的事。</p></blockquote><h2 id="二、保证安全的技术措施-操作层面" tabindex="-1">二、保证安全的技术措施(操作层面) <a class="header-anchor" href="#二、保证安全的技术措施-操作层面" aria-label="Permalink to &quot;二、保证安全的技术措施(操作层面)&quot;">​</a></h2><p>靠<strong>动手操作</strong>让设备真正没电、确认没电、防止误送电。国家规范规定的技术措施是&quot;<strong>停电、验电、装设接地线、悬挂标示牌和装设遮栏</strong>&quot;(顺序记住):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>停电 ──► 验电 ──► 装设接地线 ──► 悬挂标示牌、装设遮栏</span></span></code></pre></div><table tabindex="0"><thead><tr><th>技术措施</th><th>干什么</th></tr></thead><tbody><tr><td><strong>停电</strong></td><td>断开检修设备电源,有明显的断开点(拉开隔离开关/断路器)</td></tr><tr><td><strong>验电</strong></td><td>用合格验电器确认设备确实无电(验电器先在有电设备上验证是否好用)</td></tr><tr><td><strong>装设接地线</strong></td><td>在检修设备两端(或可能来电侧)装设接地线,泄放残余电荷、防突然来电</td></tr><tr><td><strong>悬挂标示牌、装设遮栏</strong></td><td>挂&quot;禁止合闸,有人工作&quot;等标示牌,设遮栏防止误入、误送电</td></tr></tbody></table><blockquote><p>💡 记忆口诀:<strong>&quot;停、验、挂(接地线)、牌、栏&quot;</strong>。四项技术措施的顺序和内容是必背考点。</p></blockquote><h2 id="三、组织措施与技术措施的关系" tabindex="-1">三、组织措施与技术措施的关系 <a class="header-anchor" href="#三、组织措施与技术措施的关系" aria-label="Permalink to &quot;三、组织措施与技术措施的关系&quot;">​</a></h2><ul><li><strong>组织措施</strong>管&quot;人&quot;:谁来干、怎么批、怎么监护;</li><li><strong>技术措施</strong>管&quot;电&quot;:让设备确实无电、可靠接地、有人守护;</li><li>两者缺一不可:光有制度不操作,电还是带电;光会操作没制度,容易乱干。</li></ul><h2 id="四、考点提示" tabindex="-1">四、考点提示 <a class="header-anchor" href="#四、考点提示" aria-label="Permalink to &quot;四、考点提示&quot;">​</a></h2><ul><li>✅ 组织措施:工作票、许可、监护、间断/转移/终结制度。</li><li>✅ 技术措施(必背):<strong>停电、验电、装设接地线、悬挂标示牌和装设遮栏</strong>。</li><li>✅ 技术措施有<strong>顺序</strong>:先停、后验、再接地、最后挂牌设栏。</li><li>⚠️ 易混点:组织措施(管人)与技术措施(管电)别混,考题常让&quot;挑出属于技术措施的一项&quot;。</li></ul><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><ul><li>组织措施靠制度管人:票、许可、监护、终结。</li><li>技术措施靠操作管电:停、验、挂地线、牌栏。</li><li>两者结合,才构成完整的安全作业保障。</li></ul><h2 id="六、自测练习" tabindex="-1">六、自测练习 <a class="header-anchor" href="#六、自测练习" aria-label="Permalink to &quot;六、自测练习&quot;">​</a></h2><ol><li>(单选)下列属于保证安全的技术措施的是()。 A. 工作票制度　B. 验电　C. 工作监护制度　D. 工作许可制度</li><li>(判断)保证安全的技术措施包括停电、验电、装设接地线、悬挂标示牌和装设遮栏。( )</li><li>(判断)验电时,验电器应先在带电设备上验证其是否完好。( )</li><li>(单选)下列属于保证安全的组织措施的是()。 A. 停电　B. 装设接地线　C. 工作票制度　D. 悬挂标示牌</li><li>(判断)装设接地线的作用是泄放残余电荷、防止突然来电,保护检修人员。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。验电是技术措施;其余是组织措施。</li><li><strong>√</strong>。停、验、挂地线、牌栏四项技术措施。</li><li><strong>√</strong>。先在有电设备上验证验电器完好。</li><li><strong>C</strong>。工作票制度属组织措施。</li><li><strong>√</strong>。接地线泄放电荷、防突然来电。</li></ol></details>',22)])])}const q=o(i,[["render",l]]);export{g as __pageData,q as default};
